135		}
136		if r.CanUse {
137			t.Fatalf("最近证书超差时器具不应可用，得到 reasons=%v", r.Reasons)
138		}
139		if !containsReason(r.Reasons, "超差") || !containsReason(r.Reasons, "C-NEW") {
140			t.Fatalf("拒绝原因应针对较新证书 C-NEW 超差，得到 %v", r.Reasons)
141		}
142		if containsReason(r.Reasons, "C-OLD") {
143			t.Fatalf("计划关联的较早合格证书不应出现在使用拒绝原因中：%v", r.Reasons)
144		}
145		if r.Latest == nil || r.Latest.Number != "C-NEW" || r.Latest.Pass || r.Latest.Expired {
146			t.Fatalf("最近证书应仍是较新的超差、未到期证书 C-NEW：%+v", r.Latest)
147		}
148		if len(r.History) != 2 {
149			t.Fatalf("历史应有两张证书，得到 %d", len(r.History))
150		}
151		if r.History[0].Number != "C-NEW" || r.History[0].Pass {
152			t.Fatalf("历史第一张应为较新超差证书 C-NEW，得到 %+v", r.History[0])
153		}
154		if r.History[1].Number != "C-OLD" || !r.History[1].Pass || r.History[1].Expired {
155			t.Fatalf("历史第二张应为较早合格未到期证书 C-OLD，得到 %+v", r.History[1])
156		}
157		if len(r.Plans) != 1 {
158			t.Fatalf("应只有一项计划，得到 %d", len(r.Plans))
159		}
160		p := r.Plans[0]
161		if p.Status != PlanStatusDone ||
162			p.CertificateNumber != "C-OLD" || p.CompletedAt != completedAt {
163			t.Fatalf("核对中的计划应显示已完成并保留 C-OLD 与原完成时间：%+v", p.Plan)
164		}
165		assertCertAndInstrumentUnchanged(t, l, map[string]Certificate{
166			"C-NEW": {CalDate: "2026-09-20", Expiry: "2027-09-20", Error: 0.8},
167			"C-OLD": {CalDate: "2026-09-10", Expiry: "2027-09-10", Error: -0.1},
168		})
169	
170		// 随后申请使用：被拒绝，拒绝原因针对较新证书 C-NEW 超差，并冻结留痕；
171		// 不会因为计划关联了合格的 C-OLD 而获准。
172		d, err := l.RequestUse("M-1")
173		if err != nil {
174			t.Fatalf("request use: %v", err)
175		}
176		if d.Allowed || !containsReason(d.Reasons, "超差") || !containsReason(d.Reasons, "C-NEW") {
177			t.Fatalf("使用申请应因较新证书超差被拒绝，得到 allowed=%v reasons=%v", d.Allowed, d.Reasons)
178		}
179		if containsReason(d.Reasons, "C-OLD") {
180			t.Fatalf("拒绝原因不应涉及计划关联的 C-OLD：%v", d.Reasons)
181		}
182		r2, _ := l.Review("M-1")
183		if len(r2.Rejections) != 1 {
184			t.Fatalf("应留下 1 条拒绝记录，得到 %d", len(r2.Rejections))
185		}
186		if !containsReason(r2.Rejections[0].Reasons, "超差") ||
187			!containsReason(r2.Rejections[0].Reasons, "C-NEW") {
188			t.Fatalf("留痕原因应保留较新证书超差：%+v", r2.Rejections[0])
189		}
190	
191		// 已用于完成 PL-1 的 C-OLD 不能再完成其他计划。这里直接在台账中补建一项
192		// 建立于 2026-09-10 的未结束计划（使归属与校准日期边界都通过），确认
193		// “未用于完成其他计划”仍是一条独立的拒绝条件，与证书是否最近无关。
194		l.data.Plans = append(l.data.Plans, Plan{
195			Number: "PL-2", InstrumentID: "M-1",
196			PlannedDate: "2026-09-15", OriginalDate: "2026-09-15",
197			Note: "下一轮", CreatedAt: "2026-09-10T00:00:00Z", Status: PlanStatusOpen,
198		})
199		if _, _, err := l.CompletePlan("PL-2", "C-OLD"); !IsValidation(err) ||
200			!strings.Contains(err.Error(), "已用于完成计划") {
201			t.Fatalf("已完成过 PL-1 的 C-OLD 应被拒绝用于 PL-2，得到 %v", err)
202		}
203		if p2 := l.findPlan("PL-2"); p2.Status != PlanStatusOpen ||
204			p2.CompletedAt != "" || p2.CertificateNumber != "" {
205			t.Fatalf("被拒绝的 PL-2 不应写入完成信息：%+v", p2)
206		}
207		if p1 := l.findPlan("PL-1"); p1.CertificateNumber != "C-OLD" {
208			t.Fatalf("PL-1 与 C-OLD 的关联不应被影响：%+v", p1)
209		}
210	}
211	
212	// TestHistoricalFailingCertCompletesButNewerPassingCertStillGovernsUse 保住相反
213	// 结论：较早证书超差、较新证书合格且未到期，器具在用。较早的超差证书同样可以
214	// 完成符合条件的计划；核对与使用申请仍以较新证书为准，申请获准并留痕。完成动作
215	// 不更改器具允许误差、状态、两张证书的测得误差或有效期。
216	func TestHistoricalFailingCertCompletesButNewerPassingCertStillGovernsUse(t *testing.T) {
217		clock := &fakeClock{t: mustDate(t, "2026-09-01")}
218		l := newTestLedger(t, clock)
219		mustRegister(t, l, "M-1", "万用表", 0.5)
220		if err := l.SetStatus("M-1", StatusInUse); err != nil {
221			t.Fatalf("set in-use: %v", err)
222		}
223		mustPlan(t, l, PlanInput{
224			Number: "PL-1", InstrumentID: "M-1", Date: "2026-10-20", Note: "年度例行校准",
225		})
226	
227		// 较新证书合格。
228		clock.t = mustDate(t, "2026-09-20")
229		mustAddCert(t, l, CertificateInput{
230			InstrumentID: "M-1", Number: "C-NEW", CalDate: "2026-09-20",
231			Expiry: "2027-09-20", Method: "规范A", Error: 0.1, Summary: "较新一次校准",
232		})
233		// 补录较早的超差证书（误差 5）。
234		clock.t = mustDate(t, "2026-09-25")
235		mustAddCert(t, l, CertificateInput{
236			InstrumentID: "M-1", Number: "C-OLD", CalDate: "2026-09-10",
237			Expiry: "2027-09-10", Method: "规范A", Error: 5, Summary: "补录的较早校准",
238		})
239		assertPlanStillOpen(t, l, "PL-1")
240	
241		// 较早的超差证书同样表示校准工作已完成，可以结束计划。
242		done, idem, err := l.CompletePlan("PL-1", "C-OLD")
243		if err != nil || idem {
244			t.Fatalf("较早超差证书也应能完成计划，err=%v idempotent=%v", err, idem)
245		}
246		if done.Status != PlanStatusDone || done.CertificateNumber != "C-OLD" || done.CompletedAt == "" {
247			t.Fatalf("完成结果应保留这张超差历史证书的编号与完成时间：%+v", done)
248		}
249	
250		// 核对（10-05）：最近证书是较新的合格 C-NEW，器具可以使用；历史按
251		// 校准日期由近到远，较早的 C-OLD 仍如实显示超差。
252		clock.t = mustDate(t, "2026-10-05")
253		r, err := l.Review("M-1")
254		if err != nil {
255			t.Fatalf("review: %v", err)
256		}
257		if !r.CanUse || len(r.Reasons) != 0 {
258			t.Fatalf("最近证书合格未到期时应可以使用，得到 reasons=%v", r.Reasons)
259		}
260		if r.Latest == nil || r.Latest.Number != "C-NEW" || !r.Latest.Pass || r.Latest.Expired {
261			t.Fatalf("最近证书应是较新的合格未到期证书 C-NEW：%+v", r.Latest)
262		}
263		if len(r.History) != 2 ||
264			r.History[0].Number != "C-NEW" || !r.History[0].Pass ||
265			r.History[1].Number != "C-OLD" || r.History[1].Pass {
266			t.Fatalf("历史应由近到远为合格 C-NEW、超差 C-OLD：%+v", r.History)
267		}
268		if len(r.Plans) != 1 || r.Plans[0].Status != PlanStatusDone ||
269			r.Plans[0].CertificateNumber != "C-OLD" {
270			t.Fatalf("计划应保留与较早超差证书的关联：%+v", r.Plans)
271		}
272		assertCertAndInstrumentUnchanged(t, l, map[string]Certificate{
273			"C-NEW": {CalDate: "2026-09-20", Expiry: "2027-09-20", Error: 0.1},
274			"C-OLD": {CalDate: "2026-09-10", Expiry: "2027-09-10", Error: 5},
275		})
276	
277		// 使用申请以较新证书为准，获准并留痕。
278		d, err := l.RequestUse("M-1")
279		if err != nil {
280			t.Fatalf("request use: %v", err)
281		}
282		if !d.Allowed || len(d.Reasons) != 0 {
283			t.Fatalf("应获准使用，得到 allowed=%v reasons=%v", d.Allowed, d.Reasons)
284		}
285		r2, _ := l.Review("M-1")
286		if len(r2.Rejections) != 0 {
287			t.Fatalf("获准使用不应产生拒绝记录，得到 %d 条", len(r2.Rejections))
288		}
289		recs := l.UsageRecords()
290		if len(recs) != 1 || !recs[0].Allowed {
291			t.Fatalf("应留下 1 条获准记录，得到 %+v", recs)
292		}
293	}
294	
295	// TestCompletePlanCertDateBoundaryAroundCreationDay 日期边界围绕计划最初建立的
296	// 本机日期：校准日期等于建立日期可完成，早一天则明确拒绝；拒绝后计划继续未完成
297	// 并留在待办，不写入完成时间或关联证书，随后仍可用边界当天的证书正常完成。
298	func TestCompletePlanCertDateBoundaryAroundCreationDay(t *testing.T) {
299		// 计划建立于 2026-09-10；完成动作发生在更晚的 09-15，比较只以保存的
300		// 建立日期为准，而不是操作当天。
301		clock := &fakeClock{t: mustDate(t, "2026-09-10")}
302		l := newTestLedger(t, clock)
303		mustRegister(t, l, "M-1", "万用表", 0.5)
304		mustPlan(t, l, PlanInput{
305			Number: "PL-1", InstrumentID: "M-1", Date: "2026-09-20", Note: "周期校准",
306		})
307	
308		clock.t = mustDate(t, "2026-09-15")
309		mustAddCert(t, l, CertificateInput{
310			InstrumentID: "M-1", Number: "C-TOO-EARLY", CalDate: "2026-09-09",
311			Expiry: "2027-09-09", Method: "m", Error: 0.1, Summary: "早一天",
312		})
313		_, _, err := l.CompletePlan("PL-1", "C-TOO-EARLY")
314		if !IsValidation(err) ||
315			!strings.Contains(err.Error(), "早于") || !strings.Contains(err.Error(), "建立日期") {
316			t.Fatalf("校准日期早于建立日期一天应明确拒绝并说明边界，得到 %v", err)
317		}
318		assertPlanStillOpen(t, l, "PL-1")
319		// 被拒绝的证书本身仍是一张正常历史证书，不被删除。
320		if l.findCertificate("C-TOO-EARLY") == nil {
321			t.Fatal("日期不符的拒绝不应删除证书")
322		}
323	
324		// 校准日期恰好等于建立日期：可以完成；完成时间取本次成功操作。
325		mustAddCert(t, l, CertificateInput{
326			InstrumentID: "M-1", Number: "C-ON-DAY", CalDate: "2026-09-10",
327			Expiry: "2027-09-10", Method: "m", Error: 0.1, Summary: "建立当天",
328		})
329		done, idem, err := l.CompletePlan("PL-1", "C-ON-DAY")
330		if err != nil || idem {
331			t.Fatalf("校准日期等于建立日期应可完成，err=%v idempotent=%v", err, idem)
332		}
333		if done.Status != PlanStatusDone || done.CertificateNumber != "C-ON-DAY" ||
334			!strings.HasPrefix(done.CompletedAt, "2026-09-15T") {
335			t.Fatalf("边界当天完成结果异常：%+v", done)
336		}
337		if items, _ := l.Todos(""); len(items) != 0 {
338			t.Fatalf("完成后待办应为空，得到 %+v", items)
339		}
340	
341		// 已完成后再用那张早一天的证书试图更换关联：仍拒绝，原完成信息不变。
342		_, _, err = l.CompletePlan("PL-1", "C-TOO-EARLY")
343		if !IsValidation(err) {
344			t.Fatalf("已完成计划换证书应拒绝，得到 %v", err)
345		}
346		p := l.findPlan("PL-1")
347		if p.Status != PlanStatusDone || p.CertificateNumber != "C-ON-DAY" ||
348			p.CompletedAt != done.CompletedAt {
349			t.Fatalf("拒绝换证书后原完成信息被改动：%+v", p)
350		}
351	}
