152	// 先登记较新证书再补录较早证书，用较早证书完成计划后，最近证书仍是较新的超差
153	// 证书，使用申请被拒绝并按较新证书超差留痕。
154	func TestCLIHistoricalPassingCertCompletesButUseFollowsNewerFailingCert(t *testing.T) {
