161		newer := historicalCertArgs(t, path, "C-NEW", daysAgo(t, 10), "0.8")
162		if r := runArgs(t, newer...); r.code != 0 || !strings.Contains(r.stdout, "判定：超差") {
163			t.Fatalf("较新超差证书应录入成功：code=%d stdout=%q stderr=%s", r.code, r.stdout, r.stderr)
164		}
165		older := historicalCertArgs(t, path, "C-OLD", daysAgo(t, 30), "-0.1")
166		if r := runArgs(t, older...); r.code != 0 || !strings.Contains(r.stdout, "判定：合格") {
167			t.Fatalf("较早合格证书应录入成功：code=%d stdout=%q stderr=%s", r.code, r.stdout, r.stderr)
168		}
169		// 仅录入两张证书：计划仍未完成，留在待办。
170		assertPlanOpenInCLI(t, path)
171	
172		// 用较早、非最近的合格证书完成计划：普通与 JSON 同为成功（退出 0）。
173		assertCompleteSuccess(t, path, "PL-1", "C-OLD")
174	
175		// 完成后计划移出待办。
176		if tv := runArgs(t, "todos", "-f", path, "--json"); !strings.Contains(tv.stdout, `"count": 0`) {
177			t.Fatalf("完成后计划应从待办移除：%s", tv.stdout)
178		}
179	
180		// 按器具核对：计划关联 C-OLD 且已完成；最近证书仍是较新的超差 C-NEW，
181		// 器具不可用，原因针对 C-NEW；历史按校准日期由近到远；器具状态、允许
182		// 误差与两张证书的误差、有效期都不被完成动作改动。
183		rv := runArgs(t, "review", "--id", "M-1", "-f", path, "--json")
184		if rv.code != 0 {
185			t.Fatalf("review 失败 code=%d stderr=%s", rv.code, rv.stderr)
186		}
187		var view struct {
188			CanUse  bool     `json:"can_use"`
189			Reasons []string `json:"reasons"`
190			Latest  *struct {
191				Number  string  `json:"number"`
192				Pass    bool    `json:"pass"`
193				Expired bool    `json:"expired"`
194				Error   float64 `json:"error"`
195				Expiry  string  `json:"expiry"`
196			} `json:"latest"`
197			History []struct {
198				Number string  `json:"number"`
199				Pass   bool    `json:"pass"`
200				Error  float64 `json:"error"`
201			} `json:"history"`
202			Instrument struct {
203				Status       string  `json:"status"`
204				AllowedError float64 `json:"allowed_error"`
205			} `json:"instrument"`
206			Plans []struct {
207				Status            string `json:"status"`
208				CertificateNumber string `json:"certificate_number"`
209				CompletedAt       string `json:"completed_at"`
210			} `json:"plans"`
211		}
212		if err := json.Unmarshal([]byte(rv.stdout), &view); err != nil {
213			t.Fatalf("review JSON 解析失败: %v\n%s", err, rv.stdout)
214		}
215		if view.CanUse || !containsStd(view.Reasons, "超差") || !containsStd(view.Reasons, "C-NEW") {
216			t.Fatalf("核对应因较新证书 C-NEW 超差判不可用：canUse=%v reasons=%v", view.CanUse, view.Reasons)
217		}
218		if containsStd(view.Reasons, "C-OLD") {
219			t.Fatalf("使用原因不应涉及计划关联的合格证书 C-OLD：%v", view.Reasons)
220		}
221		if view.Latest == nil || view.Latest.Number != "C-NEW" || view.Latest.Pass || view.Latest.Expired {
222			t.Fatalf("最近证书应仍是较新、未到期的超差 C-NEW：%+v", view.Latest)
223		}
224		if len(view.History) != 2 ||
225			view.History[0].Number != "C-NEW" || view.History[0].Pass ||
226			view.History[1].Number != "C-OLD" || !view.History[1].Pass {
227			t.Fatalf("历史应由近到远为超差 C-NEW、合格 C-OLD：%+v", view.History)
228		}
229		if view.History[0].Error != 0.8 || view.History[1].Error != -0.1 {
230			t.Fatalf("完成动作不得改动两张证书的测得误差：%+v", view.History)
231		}
232		if view.Instrument.Status != "在用" || view.Instrument.AllowedError != 0.5 {
233			t.Fatalf("完成动作不得更改器具状态或允许误差：%+v", view.Instrument)
234		}
235		if view.Latest.Expiry != daysAfter(t, 10*365) {
236			t.Fatalf("较新证书有效期不应被改动，得到 %s", view.Latest.Expiry)
237		}
238		if len(view.Plans) != 1 || view.Plans[0].Status != calibrate.PlanStatusDone ||
239			view.Plans[0].CertificateNumber != "C-OLD" || view.Plans[0].CompletedAt == "" {
240			t.Fatalf("核对应显示计划已完成并关联 C-OLD：%+v", view.Plans)
241		}
242	
243		// 普通文字核对也应体现同一业务结果。
244		hv := runArgs(t, "review", "--id", "M-1", "-f", path)
245		if !strings.Contains(hv.stdout, "最近证书：C-NEW") ||
246			!strings.Contains(hv.stdout, "当前能否使用：不可以") ||
247			!strings.Contains(hv.stdout, "证书 C-OLD") {
248			t.Fatalf("普通核对应展示较新超差最近证书、不可用与计划关联证书：%s", hv.stdout)
249		}
250	
251		// 随后申请使用：普通输出与 --json 都被拒绝（退出 1），原因针对 C-NEW 超差，
252		// 不能因为计划关联了合格的 C-OLD 而获准。
253		u := runArgs(t, "use", "--id", "M-1", "-f", path)
254		if u.code != 1 || !strings.Contains(u.stderr, "超差") ||
255			!strings.Contains(u.stderr, "C-NEW") || strings.Contains(u.stderr, "C-OLD") {
256			t.Fatalf("使用申请应因 C-NEW 超差拒绝且不提 C-OLD：code=%d stderr=%q", u.code, u.stderr)
257		}
258		uj := runArgs(t, "use", "--id", "M-1", "-f", path, "--json")
259		if uj.code != 1 || !strings.Contains(uj.stdout, `"allowed": false`) ||
260			!strings.Contains(uj.stdout, "超差") || !strings.Contains(uj.stdout, "C-NEW") {
261			t.Fatalf("--json 使用申请应同业务结果拒绝：code=%d stdout=%q", uj.code, uj.stdout)
262		}
263		// 拒绝留痕进入核对。
264		after := mustReviewJSON(t, path, "M-1")
265		if len(after.Rejections) != 2 ||
266			!containsStd(after.Rejections[0].Reasons, "C-NEW") ||
267			!containsStd(after.Rejections[1].Reasons, "C-NEW") {
268			t.Fatalf("两次拒绝都应按较新证书超差留痕：%+v", after.Rejections)
269		}
270	}
271	
272	// TestCLIHistoricalFailingCertCompletesButUseFollowsNewerPassingCert 反向结论：
273	// 较早证书超差、较新证书合格且未到期，器具在用。较早的超差证书同样完成计划，
274	// 核对与使用申请仍以较新证书为准，申请获准并留痕。
275	func TestCLIHistoricalFailingCertCompletesButUseFollowsNewerPassingCert(t *testing.T) {
276		dir := chdirTemp(t)
277		path := filepath.Join(dir, "台账.json")
278		seedOldPlanLedger(t, path, 60)
279	
280		if r := runArgs(t, historicalCertArgs(t, path, "C-NEW", daysAgo(t, 10), "0.1")...); r.code != 0 {
281			t.Fatalf("较新合格证书录入失败 code=%d stderr=%s", r.code, r.stderr)
282		}
283		if r := runArgs(t, historicalCertArgs(t, path, "C-OLD", daysAgo(t, 30), "5")...); r.code != 0 {
284			t.Fatalf("较早超差证书录入失败 code=%d stderr=%s", r.code, r.stderr)
285		}
286		assertPlanOpenInCLI(t, path)
287	
288		// 较早的超差证书同样可以完成计划；成功输出不得暗示器具可用。
289		assertCompleteSuccess(t, path, "PL-1", "C-OLD")
290	
291		rv := mustReviewJSON(t, path, "M-1")
292		if !rv.CanUse || len(rv.Reasons) != 0 {
293			t.Fatalf("较新证书合格未到期时应可使用，reasons=%v", rv.Reasons)
294		}
295		if rv.Latest == nil || rv.Latest.Number != "C-NEW" || !rv.Latest.Pass || rv.Latest.Expired {
296			t.Fatalf("最近证书应是较新的合格未到期 C-NEW：%+v", rv.Latest)
297		}
298		if len(rv.History) != 2 ||
299			rv.History[0].Number != "C-NEW" || !rv.History[0].Pass ||
300			rv.History[1].Number != "C-OLD" || rv.History[1].Pass {
301			t.Fatalf("历史应由近到远为合格 C-NEW、超差 C-OLD：%+v", rv.History)
302		}
303		if rv.Instrument.Status != "在用" {
304			t.Fatalf("完成动作不应更改器具状态，得到 %s", rv.Instrument.Status)
305		}
306	
307		// 使用申请以较新证书为准，获准（退出 0）并留痕。
308		u := runArgs(t, "use", "--id", "M-1", "-f", path)
309		if u.code != 0 || !strings.Contains(u.stdout, "允许使用器具 M-1") {
310			t.Fatalf("较新证书合格时应获准使用：code=%d stdout=%q stderr=%s",
311				u.code, u.stdout, u.stderr)
312		}
313		uj := runArgs(t, "use", "--id", "M-1", "-f", path, "--json")
314		if uj.code != 0 || !strings.Contains(uj.stdout, `"allowed": true`) {
315			t.Fatalf("--json 使用申请应获准：code=%d stdout=%q", uj.code, uj.stdout)
316		}
317		final := mustReviewJSON(t, path, "M-1")
318		if len(final.Rejections) != 0 {
319			t.Fatalf("获准使用不应留下拒绝记录，得到 %d 条", len(final.Rejections))
320		}
321	}
322	
323	// TestCLICompletePlanCertDateBoundary 命令行日期边界：计划建立于 30 天前。
324	// 校准日期早一天（31 天前）的证书在普通输出与 --json 下都按业务拒绝退出 1，
325	// 计划继续未完成、留在待办，不写入完成时间或关联证书；校准日期恰好等于建立
326	// 日期（30 天前）的证书可以完成，退出 0。
327	func TestCLICompletePlanCertDateBoundary(t *testing.T) {
328		dir := chdirTemp(t)
329		path := filepath.Join(dir, "台账.json")
330		seedOldPlanLedger(t, path, 30)
331	
332		// 校准日期早于计划建立日期一天。
333		if r := runArgs(t, historicalCertArgs(t, path, "C-TOO-EARLY", daysAgo(t, 31), "0.1")...); r.code != 0 {
334			t.Fatalf("早一天的证书本身应能录入：code=%d stderr=%s", r.code, r.stderr)
335		}
336		human := runArgs(t, "complete", "-f", path, "--number", "PL-1", "--certificate", "C-TOO-EARLY")
337		if human.code != 1 {
338			t.Fatalf("校准日期早于建立日期应业务拒绝退出 1，得到 %d", human.code)
339		}
340		if !strings.Contains(human.stderr, "已拒绝") ||
341			!strings.Contains(human.stderr, "早于") ||
342			!strings.Contains(human.stderr, "建立日期") {
343			t.Fatalf("普通输出应明确拒绝并说明日期边界：stderr=%q", human.stderr)
344		}
345		js := runArgs(t, "complete", "-f", path, "--json",
346			"--number", "PL-1", "--certificate", "C-TOO-EARLY")
347		if js.code != 1 || !strings.Contains(js.stdout, `"accepted": false`) {
348			t.Fatalf("--json 同样应退出 1 且 accepted=false，code=%d stdout=%q", js.code, js.stdout)
349		}
350		assertPlanOpenInCLI(t, path)
351	
352		// 校准日期等于计划最初建立的本机日期：可以完成。
353		if r := runArgs(t, historicalCertArgs(t, path, "C-ON-DAY", daysAgo(t, 30), "0.1")...); r.code != 0 {
354			t.Fatalf("建立当天的证书应能录入：code=%d stderr=%s", r.code, r.stderr)
355		}
356		ok := runArgs(t, "complete", "-f", path, "--number", "PL-1", "--certificate", "C-ON-DAY")
357		if ok.code != 0 || !strings.Contains(ok.stdout, "已完成：计划 PL-1，证书 C-ON-DAY") {
358			t.Fatalf("校准日期等于建立日期应完成成功：code=%d stdout=%q stderr=%s",
359				ok.code, ok.stdout, ok.stderr)
360		}
361		if tv := runArgs(t, "todos", "-f", path, "--json"); !strings.Contains(tv.stdout, `"count": 0`) {
362			t.Fatalf("边界当天完成后应移出待办：%s", tv.stdout)
363		}
364	}
