204			t.Fatalf("add limit cert: %v", err)
205		}
206		if !c1.Pass(0.5) {
207			t.Fatal("测得误差绝对值等于限值应判合格")
208		}
209		// 超过限值必须显示超差，结论不可由录入者选择。
210		c2, _, err := l.AddCertificate(CertificateInput{
211			InstrumentID: "M-1", Number: "C-2", CalDate: "2026-02-01",
212			Expiry: "2027-02-01", Method: "m", Error: 0.51, Summary: "s",
213		})
214		if err != nil {
215			t.Fatalf("add over-limit cert: %v", err)
216		}
217		if c2.Pass(0.5) {
218			t.Fatal("超过限值必须判超差")
219		}
220		_ = l.SetStatus("M-1", StatusInUse)
221		d, err := l.RequestUse("M-1")
222		if err != nil {
223			t.Fatalf("request use: %v", err)
224		}
225		if d.Allowed || !containsReason(d.Reasons, "超差") {
226			t.Fatalf("最近证书超差应拒绝并明确显示超差，得到 %v", d.Reasons)
227		}
