		t.Fatal("测得误差绝对值等于限值应判合格")
	}
	// 超过限值必须显示超差，结论不可由录入者选择。
	c2, _, err := l.AddCertificate(CertificateInput{
		InstrumentID: "M-1", Number: "C-2", CalDate: "2026-02-01",
