	}
	_ = l.SetStatus("M-1", StatusInUse)
	d, err := l.RequestUse("M-1")
	if err != nil {
		t.Fatalf("request use: %v", err)
	}
	if d.Allowed || !containsReason(d.Reasons, "超差") {
		t.Fatalf("最近证书超差应拒绝并明确显示超差，得到 %v", d.Reasons)
	}
