573		}
574		missing := []string{}
575		for k, v := range map[string]string{
576			"--number": *number, "--date": *date, "--reason": *reason,
577		} {
578			if strings.TrimSpace(v) == "" {
579				missing = append(missing, k)
580			}
581		}
582		if len(missing) > 0 {
583			fmt.Fprintln(stderr, "reschedule 缺少必填参数：", strings.Join(missing, "、"))
584			return 2
585		}
586		p, err := l.ReschedulePlan(*number, *date, *reason)
587		if err != nil {
588			if calibrate.IsValidation(err) || errors.Is(err, calibrate.ErrNotFound) {
589				return failPlanBusiness(opts, stdout, stderr, err, nil)
590			}
591			return failIO(stderr, err)
592		}
593		human := fmt.Sprintf("计划 %s 已改期为 %s（第 %d 次改期）。\n",
594			p.Number, p.PlannedDate, len(p.Changes))
595		return emit(opts, stdout, stderr, human, map[string]any{"accepted": true, "plan": p})
